public class TP003 {

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int kNumber1;
		int kNumber2;
		kNumber1=50;
		kNumber2=10;
		System.out.printf("%d + %d = %d\n",kNumber1,kNumber2,kNumber1+kNumber2);
		System.out.printf("%d - %d = %d\n",kNumber1,kNumber2,kNumber1-kNumber2);
		System.out.printf("%d * %d = %d\n",kNumber1,kNumber2,kNumber1*kNumber2);
		System.out.printf("%d / %d = %d\n",kNumber1,kNumber2,kNumber1/kNumber2);
	}

}
